INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ea70f60f767f3688984c5ec3aa3a578a6a95317a/content/books/zizhi-tongjian/vol-293/year-0956/part-05/sources/library/jiuwudaishi-116-july-956/source.txt", "note": "《旧五代史》卷一百十六，段落 jiu-wudaishi-205deb4a7860-p002758；EPUB电子本，纸本及异文待核", "id": "f3e3c8d0-ce1a-5fcd-9ab6-6eb1f0ad5f59"}, {"title": "宋史·巻四百八十三", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ea70f60f767f3688984c5ec3aa3a578a6a95317a/content/books/zizhi-tongjian/vol-293/year-0956/part-05/sources/library/songshi-483-zhouxingfeng-appointment/source.txt", "note": "《宋史》巻四百八十三，段落 songshi-9c6e46fee832-p075187；EPUB电子本，纸本及异文待核", "id": "3cc4d68c-af96-54c9-90ce-be43167e0f79"}, {"title": "宋史·巻四百八十三", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ea70f60f767f3688984c5ec3aa3a578a6a95317a/content/books/zizhi-tongjian/vol-293/year-0956/part-05/sources/library/songshi-483-zhouxingfeng-governance/source.txt", "note": "《宋史》巻四百八十三，段落 songshi-9c6e46fee832-p075188；EPUB电子本，纸本及异文待核", "id": "2c9017e5-51ca-59d3-a449-b360484e4921"}, {"title": "资治通鉴·后周纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ea70f60f767f3688984c5ec3aa3a578a6a95317a/content/books/zizhi-tongjian/vol-293/year-0956/part-05/sources/library/tongjian-293-956-hunan-yangzhou-withdrawal/source.txt", "note": "《资治通鉴》后周纪四，段落 zizhi-tongjian-a63549944a71-p003479；电子底本待考，分段待核", "id": "c976d062-2cad-52b8-b653-331b40f65e06"}, {"title": "资治通鉴·后周纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b209265fbe734c2fa40aacb570f4fd3aa12504d1/content/books/zizhi-tongjian/vol-293/year-0956/part-04/sources/library/tongjian-293-956-may-june/source.txt", "note": "《资治通鉴》后周纪四，段落 zizhi-tongjian-a63549944a71-p003478；电子底本待考，分段待核", "id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "舒元", "aliases": ["朱元", "硃元"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沈丘人，早先以游士身份投靠李守贞。李守贞被后汉围攻后，让他改姓朱，赴南唐求援。《新五代史》记求援者为朱元。生卒年尚未确定。", "biography": null, "status": "draft", "id": "4747ce90-dd4b-5e0b-a0c8-7420788a2347"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "周行逢", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军副使。951年与王逵率修府士兵逃回朗州。《宋史》记为朗州武陵人，早年因犯法被编入军队，凭骁勇升任军官。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1bc0f62b-e1c1-5468-a9db-2d2d5444ab22"}, {"name": "刘光委", "aliases": ["劉光委"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "湖南邵州刺史。《通鉴》记周行逢派人探察诸州，收到他多宴饮的报告后怀疑谋害自己，将刘召回杀死。是否确有谋反没有证据，死亡具体年日未载。", "biography": null, "status": "draft", "id": "7f67d2d9-8000-57be-a49a-86342881bd85"}, {"name": "张文表", "aliases": ["張文表"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朗州人、刘言麾下牙将。952年任指挥使。史书称其善战，与周行逢、潘叔嗣交好、共同成事。生卒年未载。", "biography": null, "status": "draft", "id": "2a798366-dcd5-5e9c-a10a-a03e10aaa852"}, {"name": "邓氏（周行逢妻）", "aliases": ["鄧氏（周行逢妻）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "周行逢的妻子，封郧国夫人，姓名未载。《通鉴》称其刚决、善理家产，劝丈夫减少严刑，后来居村墅不回府，并亲自输税，要求节度使率先守例。与其他邓氏分档。", "biography": null, "status": "draft", "id": "9d8e88be-d9b7-52fa-9e86-87ebd9eac974"}, {"name": "唐德", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "周行逢的女婿。曾请求补吏，周认为其不适任而不予官职，给耕牛、农具让其务农。生卒年与此事确切年份未载。", "biography": null, "status": "draft", "id": "3b00fc3b-6b07-5e60-aae0-20394b75794e"}, {"name": "徐仲雅", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚王马希范的幕僚，939年天策府开府时获任学士。生卒年未载。", "biography": null, "status": "draft", "id": "59391753-83cd-5db6-ac4a-6162aa533f37"}, {"name": "仁及", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "受周行逢信任的僧人，参与军府事务并获加检校司空。《通鉴》还记其娶数妻、出入导从如王公。具体任用年日、生卒年及各妻姓名未载。", "biography": null, "status": "draft", "id": "0ff488b9-dacc-5b78-b720-b8480b38421e"}, {"name": "符氏（柴荣宣懿皇后）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "符彦卿之女、符存审之孙女，先嫁李守贞之子李崇训。河中城陷时躲过丈夫的杀害，郭威将她送回父亲处；后嫁柴荣，954年四月被立为皇后。与柴荣后来所立符氏皇后区分；生卒年待后续相应史料校核。", "biography": null, "status": "draft", "id": "5fc1e8cd-d993-547b-a735-fe29fb2346df"}, {"name": "郭令图", "aliases": ["郭令圖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周行舒州刺史。956年三月攻取舒州后，被舒州人驱逐；王审琦夜袭恢复后，郭令图得回城。生卒年未载。", "biography": null, "status": "draft", "id": "119973d0-2d51-537e-aa8c-ade51c24d2eb"}, {"name": "杨讷", "aliases": ["楊訥", "李平"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "嵩山道士，早先以游士身份投靠李守贞。李守贞被后汉围攻后，让他改姓李、名平，与舒元通过隐秘道路到南唐求援。生卒年未载。", "biography": null, "status": "draft", "id": "2e43b907-5e6b-52bd-8ad9-35801725e3b9"}, {"name": "向训", "aliases": ["向訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。951年与陈思让参与虒亭战事，《旧五代史》称监军，《宋史》称都监。生卒年及后续改名尚未据本次引文录入。", "biography": null, "status": "draft", "id": "1d29bcb9-6ec9-5369-89ff-ea67f0460acc"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "李璟听朱元论用兵后，命其领军收复江北诸州", "start_year": 956, "end_year": 956, "time_original": "956年六月寿州南寨失利之后、七月条以前，具体日未载", "dynasty": "五代十国", "description": "李璟听朱元论用兵后，命其领军收复江北诸州。", "phases": [], "location_name": "南唐朝廷至江北", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b5830120-7604-53c8-baa7-4749bdd5ee41"}, {"title": "柴荣正式任周行逢为武平节度使，制置武安、静江军务", "start_year": 956, "end_year": 956, "time_original": "956年七月辛卯朔", "dynasty": "五代十国", "description": "柴荣正式任周行逢为武平节度使，制置武安、静江军务。", "phases": [], "location_name": "武平、武安、静江", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "642b0509-ef9a-571e-a428-96e6ac1a49e2"}, {"title": "周行逢接管湖湘后，去除马氏横赋并选廉平官员", "start_year": null, "end_year": null, "time_original": "956年兼总湖湘之后的治理概述，具体各项实施年日未载", "dynasty": "五代十国", "description": "周行逢接管湖湘后，去除马氏横赋并选廉平官员。", "phases": [], "location_name": "湖南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "0173f10d-f5d9-5e7d-89e7-378caecbb05e"}, {"title": "周行逢严惩骄横旧部，将士怨惧", "start_year": null, "end_year": null, "time_original": "周行逢统治湖南期间的概述，具体起止年未载", "dynasty": "五代十国", "description": "周行逢严惩骄横旧部，将士怨惧。", "phases": [], "location_name": "朗州及湖南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "4e590667-3e7c-5ebf-84d3-100ca1e7bcde"}, {"title": "周行逢在诸将宴会上拘捕谋乱者，斥责后当场杀死", "start_year": null, "end_year": null, "time_original": "周行逢在湖南任职期间，具体年日未载", "dynasty": "五代十国", "description": "《通鉴》记一名大将与同党十余人谋乱，周行逢得知后在宴席拘捕，斥责自己节用实库是为将士，当场打死他们。其余将领震惧，他又说其他人无罪，继续宴饮。姓名与精确总人数未载，不扩大为全部将领。", "phases": [], "location_name": "诸将宴席，具体地点未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "80873434-289d-56ea-bf61-ef9cd38b90ec"}, {"title": "周行逢常派人秘密探察诸州事务", "start_year": null, "end_year": null, "time_original": "周行逢任内习惯，具体年日未载", "dynasty": "五代十国", "description": "周行逢常派人秘密探察诸州事务。", "phases": [], "location_name": "湖南诸州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c14a3f07-68aa-5249-b6df-1e4dcff820ce"}, {"title": "周行逢因刘光委多宴饮而疑其谋害，召回并杀死", "start_year": null, "end_year": null, "time_original": "周行逢任内，具体死亡年日未载", "dynasty": "五代十国", "description": "周行逢因刘光委多宴饮而疑其谋害，召回并杀死。", "phases": [], "location_name": "邵州至召还处", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ffd4a341-bf14-594c-9248-281abf44c6f6"}, {"title": "张文表怕获罪，请回衡州，厚献馈物并谨事左右", "start_year": null, "end_year": null, "time_original": "周行逢统湖南期间，具体年日未载", "dynasty": "五代十国", "description": "张文表怕获罪，请回衡州，厚献馈物并谨事左右。", "phases": [], "location_name": "衡州及湖南军府", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ec94e8cf-da10-5c31-b8ed-ed3b1c625a17"}, {"title": "邓氏劝周行逢法太严会疏远人心，周不听", "start_year": null, "end_year": null, "time_original": "周行逢任内旧事，具体年日未载", "dynasty": "五代十国", "description": "邓氏劝周行逢法太严会疏远人心，周不听。", "phases": [], "location_name": "湖南府中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "6a734a1a-67cf-5ee5-98b3-b200bd7b3fc5"}, {"title": "邓氏不悦，往村墅看田后不回府，屡拒周行逢迎请", "start_year": null, "end_year": null, "time_original": "劝谏争执之后，具体年日未载", "dynasty": "五代十国", "description": "邓氏不悦，往村墅看田后不回府，屡拒周行逢迎请。", "phases": [], "location_name": "湖南府舍至村墅", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "36255f85-2a30-5151-8c5e-7109c0934129"}, {"title": "邓氏亲输税，要求节度使先守法率下，并因担忧滥杀拒回府", "start_year": null, "end_year": null, "time_original": "邓氏住村墅以后，具体输税年日未载", "dynasty": "五代十国", "description": "邓氏亲率僮仆输税，说明税属官府，节度使家须先守例才可率下。她提醒周行逢过去任里正曾代人缴税避罚，并因担忧滥杀会引变乱、村居便于避难而拒回府；僚属认为其言直，劝周采纳。旧里正经历是她回忆，叛乱风险是她判断，不作当前已经发生的事实。", "phases": [], "location_name": "湖南税所及村墅", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ba283b86-e85d-5288-8d9b-b9790fdc5d8d"}, {"title": "周行逢拒女婿唐德求官，给耕牛农具让其务农", "start_year": null, "end_year": null, "time_original": "周行逢在镇期间旧事，具体年日未载", "dynasty": "五代十国", "description": "周行逢拒女婿唐德求官，给耕牛农具让其务农。", "phases": [], "location_name": "湖南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9c2d870f-5a80-5f86-b692-3b211db812e7"}, {"title": "有人建议周行逢除去面上刑痕，他举黥布为例而不羞", "start_year": null, "end_year": null, "time_original": "周行逢为地方长官后，具体年日未载", "dynasty": "五代十国", "description": "有人建议周行逢除去面上刑痕，他举黥布为例而不羞。", "phases": [], "location_name": "湖南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "88faecd1-5899-50e4-be58-a092059435fb"}, {"title": "《通鉴》概述刘言、王逵以来湖南因战功授检校三公者众多", "start_year": null, "end_year": null, "