"id": "96c444e1-1250-5285-8b8f-43fee5cb2ba1", "subject_id": "6a734a1a-67cf-5ee5-98b3-b200bd7b3fc5", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "邓氏（周行逢妻）：劝丈夫减少严刑。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p034·原文件第39行", "note": "原文：尝谏行逢用法太严，人无亲附者。行逢怒曰：“汝妇人何知！”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "30db3034-8b52-538e-8ec0-807e12203414", "subject_id": "ef13963c-633e-586c-b7ea-a18896a050f9", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "周行逢：以轻蔑回答拒绝意见。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p034·原文件第39行", "note": "原文：尝谏行逢用法太严，人无亲附者。行逢怒曰：“汝妇人何知！”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "614b3a20-bf2b-501b-aa40-e3b6740b61e7", "subject_id": "ae19078f-559b-5096-995c-70d757425cb8", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "event", "field_path": "description", "claim_text": "邓氏不悦，往村墅看田后不回府，屡拒周行逢迎请。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p034·原文件第39行", "note": "原文：邓氏不悦，因请之村墅视田园，遂不复归府舍。行逢屡遣人迎之，不至。；核对说明：去村不等离婚或亡故，不补具体庄园坐标。", "status": "draft", "id": "d9e95a5f-720d-515b-b727-1bc9b2e2f070", "subject_id": "36255f85-2a30-5151-8c5e-7109c0934129", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "劝谏争执之后，具体年日未载", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p034·原文件第39行", "note": "原文：邓氏不悦，因请之村墅视田园，遂不复归府舍。行逢屡遣人迎之，不至。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "c236b71b-fa77-5acc-b22a-4b568088ea79", "subject_id": "36255f85-2a30-5151-8c5e-7109c0934129", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "邓氏（周行逢妻）：到村墅后不再回府。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p034·原文件第39行", "note": "原文：邓氏不悦，因请之村墅视田园，遂不复归府舍。行逢屡遣人迎之，不至。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "d4e63358-036a-508b-94c5-e133a4faf885", "subject_id": "73e78db0-9c24-5d98-befc-699398869197", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "周行逢：屡遣人迎请未成。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p034·原文件第39行", "note": "原文：邓氏不悦，因请之村墅视田园，遂不复归府舍。行逢屡遣人迎之，不至。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "4be442d4-9323-5b0d-b46a-ff2cfd26f3a8", "subject_id": "f1144266-de83-5728-af14-2b227ec0d2d0", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "event", "field_path": "description", "claim_text": "邓氏亲率僮仆输税，说明税属官府，节度使家须先守例才可率下。她提醒周行逢过去任里正曾代人缴税避罚，并因担忧滥杀会引变乱、村居便于避难而拒回府；僚属认为其言直，劝周采纳。旧里正经历是她回忆，叛乱风险是她判断，不作当前已经发生的事实。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p034·原文件第39行", "note": "原文：一旦，自帅僮仆来输税，行逢就见之，曰：“吾为节度使，夫人何自苦如此！”邓氏曰：“税，官物也。公为节度使，不先输税，何以率下！且独不记为里正代人输税以免楚挞时邪？”行逢欲与之归，不可，曰：“公诛杀太过，常恐一旦有变，村墅易为逃匿耳。”行逢惭怒，其僚属曰：“夫人言直，公宜纳之。”；核对说明：按原文动作分录；不外推原因与结果。", "status": "draft", "id": "31c9ad3a-f694-530e-99b7-db4ace104607", "subject_id": "ba283b86-e85d-5288-8d9b-b9790fdc5d8d", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "邓氏住村墅以后，具体输税年日未载", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p034·原文件第39行", "note": "原文：一旦，自帅僮仆来输税，行逢就见之，曰：“吾为节度使，夫人何自苦如此！”邓氏曰：“税，官物也。公为节度使，不先输税，何以率下！且独不记为里正代人输税以免楚挞时邪？”行逢欲与之归，不可，曰：“公诛杀太过，常恐一旦有变，村墅易为逃匿耳。”行逢惭怒，其僚属曰：“夫人言直，公宜纳之。”；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "cb30a203-63dc-5815-9cf9-91da8b55290f", "subject_id": "ba283b86-e85d-5288-8d9b-b9790fdc5d8d", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "邓氏（周行逢妻）：率僮仆输税，要求丈夫率先遵守并拒绝回府。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p034·原文件第39行", "note": "原文：一旦，自帅僮仆来输税，行逢就见之，曰：“吾为节度使，夫人何自苦如此！”邓氏曰：“税，官物也。公为节度使，不先输税，何以率下！且独不记为里正代人输税以免楚挞时邪？”行逢欲与之归，不可，曰：“公诛杀太过，常恐一旦有变，村墅易为逃匿耳。”行逢惭怒，其僚属曰：“夫人言直，公宜纳之。”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "7bd2492f-d9fe-56b2-8d08-0966e81f34a2", "subject_id": "e8cfa8eb-4684-5636-8731-8cb033f1e932", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "周行逢：劝妻回府，被其拒绝。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p034·原文件第39行", "note": "原文：一旦，自帅僮仆来输税，行逢就见之，曰：“吾为节度使，夫人何自苦如此！”邓氏曰：“税，官物也。公为节度使，不先输税，何以率下！且独不记为里正代人输税以免楚挞时邪？”行逢欲与之归，不可，曰：“公诛杀太过，常恐一旦有变，村墅易为逃匿耳。”行逢惭怒，其僚属曰：“夫人言直，公宜纳之。”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "7eae4aef-aac3-5121-b778-b4135f2d37ca", "subject_id": "f0d986f2-352c-5f08-88c4-b584de47d6a7", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "event", "field_path": "description", "claim_text": "周行逢拒女婿唐德求官，给耕牛农具让其务农。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p035·原文件第40行", "note": "原文：行逢婿唐德求补吏，行逢曰：“汝才不堪为吏，吾今私汝则可矣。汝居官无状，吾不敢以法贷汝，则亲戚之恩绝矣。”与之耕牛、农具而遣之。；核对说明：按原文动作分录；不外推原因与结果。", "status": "draft", "id": "9036e7d0-f26a-591d-b0f6-0220ab491f11", "subject_id": "9c2d870f-5a80-5f86-b692-3b211db812e7", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "周行逢在镇期间旧事，具体年日未载", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p035·原文件第40行", "note": "原文：行逢婿唐德求补吏，行逢曰：“汝才不堪为吏，吾今私汝则可矣。汝居官无状，吾不敢以法贷汝，则亲戚之恩绝矣。”与之耕牛、农具而遣之。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "56e54a1d-121c-587e-b270-416df8496375", "subject_id": "9c2d870f-5a80-5f86-b692-3b211db812e7", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "person", "field_path": "description", "claim_text": "唐德：以女婿身份求补吏。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p035·原文件第40行", "note": "原文：行逢婿唐德求补吏，行逢曰：“汝才不堪为吏，吾今私汝则可矣。汝居官无状，吾不敢以法贷汝，则亲戚之恩绝矣。”与之耕牛、农具而遣之。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "91a6e7f5-94ba-5a25-96c4-e1e65680d081", "subject_id": "3b00fc3b-6b07-5e60-aae0-20394b75794e", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "唐德：以女婿身份求补吏。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p035·原文件第40行", "note": "原文：行逢婿唐德求补吏，行逢曰：“汝才不堪为吏，吾今私汝则可矣。汝居官无状，吾不敢以法贷汝，则亲戚之恩绝矣。”与之耕牛、农具而遣之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "bee45d62-3ee8-58c6-a5fe-513c3f6fe074", "subject_id": "f86f97a2-a6bc-5b54-bff0-cce8ed31c1a4", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "周行逢：认为唐不适任，给农具耕牛而不任官。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p035·原文件第40行", "note": "原文：行逢婿唐德求补吏，行逢曰：“汝才不堪为吏，吾今私汝则可矣。汝居官无状，吾不敢以法贷汝，则亲戚之恩绝矣。”与之耕牛、农具而遣之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "b1b9305f-1de7-511d-8d53-d227220ecb21", "subject_id": "6b6903bb-f098-519f-85f9-1be4e75243fb", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "person_relationship", "field_path": "description", "claim_text": "周行逢是唐德的岳父。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p035·原文件第40行", "note": "原文：行逢婿唐德求补吏，；核对说明：原称婿在此指女婿，因此周行逢是唐德岳父；妻女姓名不明，未补匿名姓名。", "status": "draft", "id": "0aed04d3-ac3c-55d9-936d-bb3ee6f7c666", "subject_id": "2ca56d2c-7015-54b6-b647-986922bca8a1", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "event", "field_path": "description", "claim_text": "《宋史》也记拒绝女婿求官、给农具归农。", "citation": "《宋史》巻四百八十三，段落 songshi-9c6e46fee832-p075188；EPUB电子本，纸本及异文待核", "note": "原文：有女婿求補吏，不許，返給以耒耜，；核对说明：宋传未写唐德名，不擅补到摘录；此事未明确定956年当天。", "status": "draft", "id": "d8aeace5-31c1-5977-9533-315dbdd6b35a", "subject_id": "9c2d870f-5a80-5f86-b692-3b211db812e7", "source_id": "2c9017e5-51ca-59d3-a449-b360484e4921"}, {"subject_table": "person", "field_path": "biography", "claim_text": "《通鉴》回述周行逢年轻时犯法受黥，服役辰州铜坑。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p036·原文件第41行", "note": "原文：行逢少时尝坐事黥，隶辰州铜坑，；核对说明：少时为旧事，具体年月未载，不能当956年新受刑。", "status": "draft", "id": "bbb78046-30f1-5af1-ae35-b081b49eb03a", "subject_id": "1bc0f62b-e1c1-5468-a9db-2d2d5444ab22", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "event", "field_path": "description", "claim_text": "有人建议周行逢除去面上刑痕，他举黥布为例而不羞。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p036·原文件第41行", "note": "原文：或说行逢：“公面有文，恐为朝廷使者所嗤，请以药灭之。”行逢曰：“吾闻汉有黥布，不害为英雄，吾何耻焉！”；核对说明：汉黥布是历史类比，没有参与这次对话；药灭只是匿名建议，不当作已实际治疗。", "status": "draft", "id": "e3885815-8d32-537c-b03b-b3f36ba6fd3e", "subject_id": "88faecd1-5899-50e4-be58-a092059435fb", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "周行逢为地方长官后，具体年日未载", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p036·原文件第41行", "note": "原文：或说行逢：“公面有文，恐为朝廷使者所嗤，请以药灭之。”行逢曰：“吾闻汉有黥布，不害为英雄，吾何耻焉！”；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "ef7b3505-b0de-5c6c-95c2-ee803fc9eb57", "subject_id": "88faecd1-5899-50e4-be58-a092059435fb", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "周行逢：拒把旧刑痕视为耻辱。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p036·原文件第41行", "note": "原文：或说行逢：“公面有文，恐为朝廷使者所嗤，请以药灭之。”行逢曰：“吾闻汉有黥布，不害为英雄，吾何耻焉！”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "4a1405c8-2af3-5b94-8e8d-868dafaaa613", "subject_id": "44bdc53f-1765-59a7-a685-c09520d638ba", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "event", "field_path": "description", "claim_text": "《通鉴》概述刘言、王逵以来湖南因战功授检校三公者众多。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p037·原文件第42行", "note": "原文：自刘言、王逵以来，屡举兵，将吏积功及所羁縻蛮夷，检校官至三公者以千数。；核对说明：以千数为史载数量概述，三公为检校加衔，不等同全国实任三公同时数千人。", "status": "draft", "id": "ccca09ad-94ce-51ca-a1c7-13581db6e5b2", "subject_id": "8103691d-6f03-5e16-b8b5-d75d333916a1", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "刘言王逵至周行逢时期的累积概述，具体授号批次未载", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p037·原文件第42行", "note": "原文：自刘言、王逵以来，屡举兵，将吏积功及所羁縻蛮夷，检校官至三公者以千数。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "718c46f7-800c-5c37-99ea-eef6f66c852c", "subject_id": "8103691d-6f03-5e16-b8b5-d75d333916a1", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "person", "field_path": "description", "claim_text": "徐仲雅：前天策府学士，自马希广被废后不再任职。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p037·原文件第42行", "note": "原文：前天策府学士徐仲雅，自马希广之废，杜门不仕，；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "6a72a66e-ceaf-5164-87db-fb079c286ee4", "subject_id": "59391753-83cd-5db6-ac4a-6162aa533f37", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "person", "field_path": "biography", "claim_text": "徐仲雅在马希广被废后闭门不仕。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p037·原文件第42行", "note": "原文：前天策府学士徐仲雅，自马希广之废，杜门不仕，；核对说明：马希广之废为旧事起点，不把退隐开始硬定956年。", "status": "draft", "id": "f95d0262-6001-5f7a-bd4b-8409791209e2", "subject_id": "59391753-83cd-5db6-ac4a-6162aa533f37", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "event", "field_path": "description", "claim_text": "周行逢慕徐仲雅，署节度判官，徐屡辞，周强召仍不接受。", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p037·原文件第42行", "note": "原文：行逢慕之，署节度判官。仲雅曰：“行逢昔趋事我，奈何为之幕吏！”辞疾不至。行逢迫胁固召之，面授文牒，终辞不取，；核对说明：署任与真正接受职务分开，不写徐已经就任判官；辞疾不证明实患病。", "status": "draft", "id": "d9543896-cbea-579f-9f99-39f3626be6d8", "subject_id": "aa462add-cc5b-5848-a117-1bf4578ff81e", "source_id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "周行逢统湖南时期，具体年日未载", "citation": "卷293·显德三年（956年六月至七月及相关追述）·zztj-v293-y0956-p037·原文件第42行", "note": "原文：行逢慕之，署节度判官。仲雅曰：“行逢昔趋事我，奈何为之幕吏！”辞疾不至。行逢迫胁固召之，面授文牒，终辞不取，；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "6ca77dbe-72c9-5cd8-93be-